package com.bombay.restaurantintelligence.whatsapp;
import org.junit.jupiter.api.Test; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.util.HexFormat; import static org.assertj.core.api.Assertions.assertThat;
class WhatsAppSignatureVerifierTest {@Test void validatesMetaHmacSignature() throws Exception {String secret="test-secret",body="{\"hello\":\"world\"}";Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));String signature="sha256="+HexFormat.of().formatHex(mac.doFinal(body.getBytes(StandardCharsets.UTF_8)));assertThat(new WhatsAppSignatureVerifier(secret).valid(body,signature)).isTrue();assertThat(new WhatsAppSignatureVerifier(secret).valid(body+"x",signature)).isFalse();}}
